INSERT INTO `saints` (`id`, `name`, `foto`, `text`, `url`) VALUES
(1, 'Священномученик\r\nАлександр Телемаков', '1496', 'Новомученик священник Александр Телемаков служил в с. Чумакино нынешнего Инзенского района Ульяновской области.\r\nПринял мученическую кончину в 1938 году.', '/telemakov.php'),
(2, 'Священномученик Владимир Пиксанов', '3234', 'Священномученик иерей Владимир Тимофеевич Пиксанов служил в нынешней р.п. Павловка Ульяновской области. Мученическую кончину принял от богоборческой власти одним из первых - в 1918 году.', '/pub_show.php?data=2016.07.19%2021:05'),
(3, 'Священномученик Нифонт (Выблов)', '2653', 'Иеромонах Нифонт служил на хуторе Березовском в Радищевском районе. Был арестован ОГПУ 28 декабря 1930 года и скончался в Сызранской тюрьме 30 августа 1931 года.', '/pub_show.php?data=2015.11.10%2018:05');
